from typing import Annotated
from fastapi import Depends, FastAPI

class Contains:
    def __init__(self, required: str):
        self.required = required

    def __call__(self, q: str = "") -> bool:
        return self.required.lower() in q.lower()

contains_fastapi = Contains("fastapi")
app = FastAPI()

@app.get("/check")
async def check_query(matches: Annotated[bool, Depends(contains_fastapi)]) -> dict[str, bool]:
    return {"matches": matches}

from typing import Annotated
from fastapi import Cookie, Depends, FastAPI

app = FastAPI()

def query_extractor(q: str | None = None) -> str | None:
    return q

def query_or_cookie(
    query: Annotated[str | None, Depends(query_extractor)],
    last_query: Annotated[str | None, Cookie()] = None,
) -> str | None:
    return query or last_query

@app.get("/search")
async def search(value: Annotated[str | None, Depends(query_or_cookie)]) -> dict[str, str | None]:
    return {"value": value}

from typing import Annotated
from fastapi import Depends, FastAPI

calls = 0

def next_value() -> int:
    global calls
    calls += 1
    return calls

app = FastAPI()

@app.get("/cached")
async def cached(
    first: Annotated[int, Depends(next_value)],
    second: Annotated[int, Depends(next_value)],
) -> dict[str, object]:
    return {"same": first == second, "gap": second - first}

@app.get("/fresh")
async def fresh(
    first: Annotated[int, Depends(next_value)],
    second: Annotated[int, Depends(next_value, use_cache=False)],
) -> dict[str, object]:
    return {"same": first == second, "gap": second - first}

from typing import Annotated
from fastapi import Depends, FastAPI, Header, HTTPException

app = FastAPI()

def verify_token(x_token: Annotated[str, Header()]) -> None:
    if x_token != "lab-secret":
        raise HTTPException(status_code=400, detail="Invalid token")

@app.get("/items", dependencies=[Depends(verify_token)])
async def read_items() -> dict[str, bool]:
    return {"allowed": True}

from typing import Annotated
from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException

def verify_key(x_key: Annotated[str, Header()]) -> None:
    if x_key != "admin-key":
        raise HTTPException(status_code=403, detail="Forbidden")

router = APIRouter(prefix="/admin", dependencies=[Depends(verify_key)])

@router.get("/status")
async def admin_status() -> dict[str, bool]:
    return {"admin": True}

app = FastAPI()
app.include_router(router)

