from typing import Annotated
from fastapi import Depends, FastAPI

events: list[str] = []

def resource():
    events.append("open")
    try:
        yield "db-session"
    finally:
        events.append("close")

app = FastAPI()

@app.get("/resource")
async def use_resource(value: Annotated[str, Depends(resource, scope="function")]) -> dict[str, object]:
    return {"value": value, "events_during": list(events)}

@app.get("/events")
async def read_events() -> dict[str, list[str]]:
    return {"events": events}
